const { processPayment, reserveInventory } =
  proxyActivities<Activities>({ startToCloseTimeout: '5m' });

async function myWorkflow(input: Order) {
  const payment = await processPayment(input); // Activity: real side effect
  if (payment.success) {
    await reserveInventory(input);              // Workflow: deterministic branch
  }
}

const documentSigned = defineSignal<[SignatureData]>('documentSigned');

async function documentSigningWorkflow(docId: string) {
  let signature: SignatureData | undefined;
  setHandler(documentSigned, (data) => { signature = data; });
  await sendForSignature(docId);
  await condition(() => signature !== undefined, '30 days'); // waits without a thread
}

